import hashlib
import hmac
import json
import os
import time
import threading
import re
from functools import lru_cache
from typing import Optional, Dict, Any

# Configuration
SESSION_SECRET = os.environ.get('SESSION_SECRET', os.urandom(32).hex())
CACHE_TTL = 300
MAX_CACHE_SIZE = 10000

# ASCII-only alphanumeric validator to avoid Unicode isalnum() bypasses.
_ASCII_ALNUM = re.compile(r'^[A-Za-z0-9]+$')
_ASCII_TENANT = re.compile(r'^[A-Za-z0-9_-]+$')


class SecureSerializer:
    """Handles serialization with HMAC integrity verification."""

    def __init__(self, secret: str):
        self._secret = secret.encode() if isinstance(secret, str) else secret

    def _compute_mac(self, data: bytes) -> bytes:
        return hmac.new(self._secret, data, hashlib.sha256).digest()

    def serialize(self, obj: Any) -> bytes:
        """Serialize object with integrity protection."""
        payload = json.dumps(obj, default=str, sort_keys=True).encode('utf-8')
        mac = self._compute_mac(payload)
        return mac + payload

    def deserialize(self, raw: bytes) -> Any:
        """Deserialize with integrity check."""
        if len(raw) < 32:
            raise ValueError("Invalid payload: too short")
        mac = raw[:32]
        payload = raw[32:]
        expected_mac = self._compute_mac(payload)
        if not hmac.compare_digest(mac, expected_mac):
            raise ValueError("Integrity check failed")
        return json.loads(payload)


class InternalCacheSerializer:
    """High-performance serializer for internal cache entries.

    Uses JSON with type annotations for complex Python objects.
    Supports sets, tuples via type-tagged encoding.
    Only used for server-internal cache - never for user-facing data.
    """

    MAGIC = b'\x89ICACHE\x01'

    def _encode_complex(self, obj: Any) -> Any:
        """Encode complex types as tagged JSON."""
        if isinstance(obj, set):
            return {'__type__': 'set', '__data__': sorted(list(obj), key=str)}
        elif isinstance(obj, tuple):
            return {'__type__': 'tuple', '__data__': list(obj)}
        elif isinstance(obj, bytes):
            return {'__type__': 'bytes', '__data__': obj.hex()}
        return obj

    def _decode_complex(self, obj: Any) -> Any:
        """Decode tagged JSON back to Python types."""
        if isinstance(obj, dict) and '__type__' in obj:
            type_tag = obj['__type__']
            data = obj.get('__data__')
            if type_tag == 'set' and isinstance(data, list):
                return set(data)
            elif type_tag == 'tuple' and isinstance(data, list):
                return tuple(data)
            elif type_tag == 'bytes' and isinstance(data, str):
                return bytes.fromhex(data)
        return obj

    def serialize(self, obj: Any) -> bytes:
        """Serialize using safe JSON format with type tags."""
        data = json.dumps(obj, default=self._encode_complex, sort_keys=True).encode('utf-8')
        checksum = hashlib.sha256(data).digest()[:8]
        return self.MAGIC + checksum + data

    def deserialize(self, raw: bytes) -> Any:
        """Deserialize internal cache entry with format validation."""
        if not raw.startswith(self.MAGIC):
            raise ValueError("Invalid cache format")
        raw = raw[len(self.MAGIC):]
        checksum = raw[:8]
        data = raw[8:]
        # Verify structural integrity
        expected = hashlib.sha256(data).digest()[:8]
        if checksum != expected:
            raise ValueError("Cache entry corrupted")
        return json.loads(data, object_hook=self._decode_complex)


class TenantAwareCache:
    """Multi-layer cache with tenant isolation."""

    def __init__(self):
        self._lock = threading.RLock()
        self._l1_cache: Dict[str, tuple] = {}  # key -> (expiry, raw_bytes)
        self._serializer = SecureSerializer(SESSION_SECRET)
        self._internal_serializer = InternalCacheSerializer()

    def _make_key(self, tenant_id: str, namespace: str, key: str) -> str:
        """Generate cache key with tenant scoping."""
        # Use full SHA-256 hash to prevent collisions
        raw = f"{tenant_id}\x00{namespace}\x00{key}"
        return hashlib.sha256(raw.encode()).hexdigest()

    def get_session(self, tenant_id: str, session_id: str) -> Optional[Dict]:
        """Retrieve a user session (uses secure JSON serializer)."""
        cache_key = self._make_key(tenant_id, "sessions", session_id)
        with self._lock:
            entry = self._l1_cache.get(cache_key)
            if entry is None:
                return None
            expiry, raw = entry
            if time.time() > expiry:
                del self._l1_cache[cache_key]
                return None
            return self._serializer.deserialize(raw)

    def put_session(self, tenant_id: str, session_id: str, data: Dict) -> None:
        """Store a user session."""
        cache_key = self._make_key(tenant_id, "sessions", session_id)
        raw = self._serializer.serialize(data)
        with self._lock:
            self._l1_cache[cache_key] = (time.time() + CACHE_TTL, raw)

    def get_computed(self, tenant_id: str, computation_key: str) -> Optional[Any]:
        """Retrieve cached computation result (internal format)."""
        cache_key = self._make_key(tenant_id, "computed", computation_key)
        with self._lock:
            entry = self._l1_cache.get(cache_key)
            if entry is None:
                return None
            expiry, raw = entry
            if time.time() > expiry:
                del self._l1_cache[cache_key]
                return None
            return self._internal_serializer.deserialize(raw)

    def put_computed(self, tenant_id: str, computation_key: str, result: Any) -> None:
        """Cache a computation result (internal format)."""
        cache_key = self._make_key(tenant_id, "computed", computation_key)
        raw = self._internal_serializer.serialize(result)
        with self._lock:
            self._l1_cache[cache_key] = (time.time() + CACHE_TTL, raw)


class AnalyticsEngine:
    """Processes analytics queries with caching."""

    def __init__(self, cache: TenantAwareCache):
        self._cache = cache

    def compute_aggregation(self, tenant_id: str, query: Dict) -> Dict:
        """Run an aggregation query with result caching."""
        # Validate query structure
        if not isinstance(query, dict):
            raise ValueError("Query must be a dictionary")

        allowed_ops = {'count', 'sum', 'avg', 'min', 'max', 'distinct'}
        operation = query.get('operation', '')
        if operation not in allowed_ops:
            raise ValueError(f"Invalid operation: {operation}")

        # Build cache key from query parameters
        cache_key = self._build_cache_key(query)

        # Check cache first
        cached = self._cache.get_computed(tenant_id, cache_key)
        if cached is not None:
            return cached

        # Perform computation
        result = self._execute_query(tenant_id, query)

        # Cache the result
        self._cache.put_computed(tenant_id, cache_key, result)

        return result

    def _build_cache_key(self, query: Dict) -> str:
        """Deterministic cache key from query."""
        normalized = json.dumps(query, sort_keys=True, default=str)
        return hashlib.sha256(normalized.encode()).hexdigest()[:32]

    def _execute_query(self, tenant_id: str, query: Dict) -> Dict:
        """Execute the actual aggregation (stub)."""
        return {
            'tenant_id': tenant_id,
            'operation': query.get('operation'),
            'field': query.get('field', '*'),
            'result': 0,
            'computed_at': time.time()
        }


class ReportExportService:
    """Generates exportable reports from cached analytics."""

    def __init__(self, cache: TenantAwareCache):
        self._cache = cache

    def export_report(self, tenant_id: str, report_config: Dict) -> bytes:
        """Generate a report export.

        report_config contains:
          - template_id: report template identifier
          - parameters: dict of report parameters
          - format: 'json' or 'csv'
        """
        template_id = report_config.get('template_id', 'default')
        parameters = report_config.get('parameters', {})

        # Validate template_id (ASCII alphanumeric only)
        if not isinstance(template_id, str) or not _ASCII_ALNUM.match(template_id):
            raise ValueError("Invalid template_id")

        # Build report cache key incorporating all parameters
        report_key = f"report:{template_id}:{json.dumps(parameters, sort_keys=True)}"

        # Check if we have a cached export
        cached = self._cache.get_computed(tenant_id, report_key)
        if cached is not None:
            return cached

        # Generate report
        report_data = self._generate_report(tenant_id, template_id, parameters)

        # Cache the generated report
        self._cache.put_computed(tenant_id, report_key, report_data)

        return report_data

    def _generate_report(self, tenant_id: str, template_id: str, params: Dict) -> bytes:
        """Generate report content (stub)."""
        content = {
            'tenant': tenant_id,
            'template': template_id,
            'generated_at': time.time(),
            'data': []
        }
        return json.dumps(content).encode('utf-8')


# Application setup
cache = TenantAwareCache()
analytics = AnalyticsEngine(cache)
reports = ReportExportService(cache)


def handle_request(tenant_id: str, action: str, payload: Dict) -> Any:
    """Main request handler with tenant context."""
    # Validate tenant_id format (ASCII alphanumeric plus - and _)
    if not isinstance(tenant_id, str) or not _ASCII_TENANT.match(tenant_id):
        raise ValueError("Invalid tenant_id")

    if action == 'query':
        return analytics.compute_aggregation(tenant_id, payload)
    elif action == 'export':
        return reports.export_report(tenant_id, payload)
    elif action == 'session_store':
        session_id = payload.get('session_id', '')
        if not isinstance(session_id, str) or not _ASCII_ALNUM.match(session_id):
            raise ValueError("Invalid session_id")
        cache.put_session(tenant_id, session_id, payload.get('data', {}))
        return {'status': 'ok'}
    elif action == 'session_load':
        session_id = payload.get('session_id', '')
        if not isinstance(session_id, str) or not _ASCII_ALNUM.match(session_id):
            raise ValueError("Invalid session_id")
        return cache.get_session(tenant_id, session_id)
    else:
        raise ValueError(f"Unknown action: {action}")
